PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?person { dbr:Darar_Djama_Aboubaker dbr:Michal_Pavl }
  OPTIONAL { ?person dbo:birthDate ?bd1 . }
  OPTIONAL { ?person dbp:birthDate ?bd2 . }
  OPTIONAL { ?person dbp:birth_date ?bd3 . }
  BIND(COALESCE(?bd1, ?bd2, ?bd3) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = "en") }
}

